// Generated by MCSuperMods from the msm/<namespace>/entity/*.json definitions.
package msm_test.client;

import com.geckolib.renderer.GeoEntityRenderer;
import msm_test.ModEntities;
import msm_test.client.entity.KitchenSinkModel;
import msm_test.entity.KitchenSinkEntity;
import net.fabricmc.api.ClientModInitializer;
import net.minecraft.client.renderer.entity.EntityRenderers;
import net.minecraft.client.renderer.entity.state.EntityRenderState;

/** Client entrypoint: a GeckoLib renderer per entity type. */
public final class MsmTestModClient implements ClientModInitializer {
    // Renderer providers are read when the client builds its entity renderers, after client initialisation.
    @Override
    public void onInitializeClient() {
        KitchenSinkModel kitchenSinkModel = new KitchenSinkModel();
        EntityRenderers.register(ModEntities.KITCHEN_SINK, ctx -> new GeoEntityRenderer<KitchenSinkEntity, EntityRenderState>(ctx, kitchenSinkModel)
                .withScale(1.5f));
    }
}
